function getCsrfToken(){const e=document.cookie.split(";").map(e=>e.trim()).find(e=>e.startsWith("csrf_token="));return e?decodeURIComponent(e.slice(11)):""}export async function fetchWithCsrf(e,t={}){if(["POST","PUT","DELETE"].includes((t.method||"GET").toUpperCase())){t.headers=t.headers||{};const e=getCsrfToken();e&&(t.headers["X-CSRF-Token"]=e)}return fetch(e,{credentials:"same-origin",...t})}async function parseJsonSafe(e){if("function"!=typeof e.text)return"function"==typeof e.json?e.json():null;const t=await e.text();return t?JSON.parse(t):null}function buildJsonRequestOptions(e,t,r={}){return{method:e,headers:{"Content-Type":"application/json"},...r,body:JSON.stringify(t)}}async function fetchOkJson(e,t,r){try{const r=await fetchWithCsrf(e);return r.ok?await parseJsonSafe(r):t}catch(e){return r&&console.error(r,e),t}}async function postJsonResult(e,t,r={}){try{const o=await fetchWithCsrf(e,buildJsonRequestOptions("POST",t,r.requestOptions||{}));return await parseJsonSafe(o)}catch(e){return r.fallback}}async function postBoolean(e,t,r){try{return(await fetchWithCsrf(e,buildJsonRequestOptions("POST",t))).ok}catch(e){return console.error(r,e),!1}}export const API_URL="/api/data";export const LOGIN_URL="/api/login";export const LOGOUT_URL="/api/logout";export const CHANGE_PASSWORD_URL="/api/change-password";export const PUSH_REGISTER_URL="/api/push/register";export const PUSH_UNREGISTER_URL="/api/push/unregister";export async function loadDataFromServer(e=null){return fetchOkJson(`/api/data${buildChildQuery(e)}`,null,"Failed to load from server:")}export async function loadBaseData(){return fetchOkJson("/api/base-data",{tasks:[],products:[]},"Failed to load base data:")}export async function saveDataToServer(e,t={}){try{const r=await fetchWithCsrf(API_URL,{method:"POST",headers:{"Content-Type":"application/json"},keepalive:!0===t.keepalive,body:JSON.stringify(e)});if(!r.ok){let e="";try{const t=await parseJsonSafe(r.clone());e=t?.error?`: ${t.error}`:""}catch(e){}console.error(`Failed to save data (${r.status})${e}`)}return r.ok}catch(e){return console.error("Failed to save to server:",e),!1}}function buildChildQuery(e){return null==e?"":`?childId=${encodeURIComponent(e)}`}async function callAction(e,t={}){try{const r=await fetchWithCsrf(e,t),o=await parseJsonSafe(r);return r.ok?{success:!0,data:o}:{success:!1,error:o?.error||"Не удалось выполнить действие"}}catch(e){return console.error("Action request failed:",e),{success:!1,error:"Ошибка сети"}}}export function completeTaskOnServer(e,t){return callAction(`/api/tasks/${encodeURIComponent(e)}/complete${buildChildQuery(t)}`,{method:"POST"})}export const requestTaskCompletionOnServer=e=>callAction(`/api/tasks/${encodeURIComponent(e)}/request`,{method:"POST"});export const purchaseItemOnServer=(e,t)=>callAction(`/api/shop/${encodeURIComponent(e)}/purchase${buildChildQuery(t)}`,{method:"POST"});export const requestItemPurchaseOnServer=e=>callAction(`/api/shop/${encodeURIComponent(e)}/request`,{method:"POST"});export const approveRequestOnServer=(e,t)=>callAction(`/api/requests/${encodeURIComponent(e)}/approve${buildChildQuery(t)}`,{method:"POST"});export const rejectRequestOnServer=(e,t)=>callAction(`/api/requests/${encodeURIComponent(e)}/reject${buildChildQuery(t)}`,{method:"POST"});export const deleteRequestOnServer=(e,t)=>callAction(`/api/requests/${encodeURIComponent(e)}${buildChildQuery(t)}`,{method:"DELETE"});export const deleteHistoryEntryOnServer=(e,t)=>callAction(`/api/history/${encodeURIComponent(e)}${buildChildQuery(t)}`,{method:"DELETE"});export const adjustBalanceOnServer=(e,t,r)=>callAction("/api/balance/adjust",buildJsonRequestOptions("POST",{childId:e,amount:t,description:r}));export async function logout(){try{return(await fetchWithCsrf(LOGOUT_URL,{method:"POST"})).ok}catch(e){return console.error("Logout failed:",e),!1}}export async function registerPushTokenOnServer(e){try{const t=await fetchWithCsrf(PUSH_REGISTER_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(e)});return t.ok?{success:!0}:await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function unregisterPushTokenOnServer(e){try{const t=await fetchWithCsrf(PUSH_UNREGISTER_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:e})});return t.ok?{success:!0}:await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function changePassword(e,t){try{const r=await fetchWithCsrf(CHANGE_PASSWORD_URL,{method:"POST",headers:{"Content-Type":"application/json"},cache:"no-store",body:JSON.stringify({oldPassword:e,newPassword:t})});if(r.ok)return{success:!0};return{success:!1,error:(await parseJsonSafe(r)).error}}catch(e){return{success:!1,error:"Ошибка сети"}}}export async function login(e,t){try{const r=await fetchWithCsrf(LOGIN_URL,{method:"POST",headers:{"Content-Type":"application/json"},cache:"no-store",body:JSON.stringify({email:e,password:t})});if(r.ok){return{success:!0,role:(await parseJsonSafe(r)).role}}return{success:!1,error:(await parseJsonSafe(r)).error,status:r.status}}catch(e){return{success:!1,error:"Network Error"}}}export async function regenerateChildToken(e){return fetchOkJson(`/api/children/${e}/regenerate-token`,null,"Failed to regenerate token:")}export const addChild=e=>postJsonResult("/api/children",{name:e},{fallback:{success:!1,error:"Network error"}});export async function deleteChild(e){try{return await parseJsonSafe(await fetchWithCsrf(`/api/children/${e}`,{method:"DELETE"}))}catch(e){return{success:!1,error:"Network error"}}}export const getChildLink=e=>fetchOkJson(`/api/children/${e}/link`,{success:!1,error:"Network error"});export const updateChildSettings=(e,t,r)=>postJsonResult(`/api/children/${t}/settings`,r,{fallback:{success:!1,error:"Network error"}});export const updateNickname=e=>postJsonResult("/api/update-nickname",{nickname:e},{fallback:{success:!1,error:"Ошибка сети"}});export const searchUsers=e=>fetchOkJson(`/api/search-user?nickname=${encodeURIComponent(e)}`,[],"Failed to search users:");export const addFriend=e=>postJsonResult("/api/add-friend",{friendId:e},{fallback:{success:!1,error:"Ошибка сети"}});export const loadFriendsList=()=>fetchOkJson("/api/friends-list",[],"Failed to load friends list:");export const savePreference=(e,t)=>postBoolean("/api/preferences",{key:e,value:t},"Failed to save preference:");export const saveChildTheme=(e,t)=>postBoolean(`/api/children/${e}/theme`,{theme:t},"Failed to save child theme:");export async function fetchAnalyticsData(e="month",t=null){return fetchOkJson(`/api/analytics?timeframe=${e}${t?`&childId=${t}`:""}`,null,"Failed to fetch analytics:")}